/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PRODUCT_ISSUANCE_OUTPUT_RULE
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PRODUCT   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 6 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PRODUCT_HK
   hashdiff    : SAT_PRODUCT_ISSUANCE_OUTPUT_RULE_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , AUTO_EMAIL_YN as AUTOMATIC_ISSUANCE_EMAIL_INDICATOR
        , AUTO_SMS_YN as AUTOMATIC_ISSUANCE_SMS_INDICATOR
        , POLICY_SCHD_YN as POLICY_SCHEDULE_PRODUCED_INDICATOR
        , POLICY_SCHD_NAME as POLICY_SCHEDULE_WORDING_NAME
        , BLOCK_SMS_IMD as INTERMEDIARY_SMS_SUPPRESSED_INDICATOR
        , BLOCK_EMAIL_IMD as INTERMEDIARY_EMAIL_SUPPRESSED_INDICATOR
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then AUTOMATIC_ISSUANCE_EMAIL_INDICATOR end) as AUTOMATIC_ISSUANCE_EMAIL_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then AUTOMATIC_ISSUANCE_SMS_INDICATOR end) as AUTOMATIC_ISSUANCE_SMS_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_SCHEDULE_PRODUCED_INDICATOR end) as POLICY_SCHEDULE_PRODUCED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then POLICY_SCHEDULE_WORDING_NAME end) as POLICY_SCHEDULE_WORDING_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then INTERMEDIARY_SMS_SUPPRESSED_INDICATOR end) as INTERMEDIARY_SMS_SUPPRESSED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then INTERMEDIARY_EMAIL_SUPPRESSED_INDICATOR end) as INTERMEDIARY_EMAIL_SUPPRESSED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when AUTOMATIC_ISSUANCE_EMAIL_INDICATOR is not null or AUTOMATIC_ISSUANCE_SMS_INDICATOR is not null or POLICY_SCHEDULE_PRODUCED_INDICATOR is not null or POLICY_SCHEDULE_WORDING_NAME is not null or INTERMEDIARY_SMS_SUPPRESSED_INDICATOR is not null or INTERMEDIARY_EMAIL_SUPPRESSED_INDICATOR is not null
                     then md5(upper(coalesce(cast(AUTOMATIC_ISSUANCE_EMAIL_INDICATOR as varchar), '') || '|' || coalesce(cast(AUTOMATIC_ISSUANCE_SMS_INDICATOR as varchar), '') || '|' || coalesce(cast(POLICY_SCHEDULE_PRODUCED_INDICATOR as varchar), '') || '|' || coalesce(cast(POLICY_SCHEDULE_WORDING_NAME as varchar), '') || '|' || coalesce(cast(INTERMEDIARY_SMS_SUPPRESSED_INDICATOR as varchar), '') || '|' || coalesce(cast(INTERMEDIARY_EMAIL_SUPPRESSED_INDICATOR as varchar), '')))
                end as SAT_PRODUCT_ISSUANCE_OUTPUT_RULE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_ISSUANCE_OUTPUT_RULE_HASHDIFF is not null
